#!/usr/bin/env python3"""Тест для проверки создания папки"""import requestsimport jsonimport timedef test_folder_creation():    """Тестировать создание папки"""    base_url = "http://localhost:8000"        # Данные для тестовой папки    folder_data = {        "name": "Тестовая папка",        "description": "Папка для тестирования",        "folder_type": "custom",        "icon": "folder",        "color": "bg-blue-500",        "is_shared": False,        "is_pinned": False,        "sort_order": 0,        "chat_ids": [],        "agent_ids": [],        "settings": {}    }        print("🧪 Тестируем создание папки...")    print(f"📋 Данные папки: {json.dumps(folder_data, indent=2, ensure_ascii=False)}")        try:        # Сначала нужно авторизоваться        print("\n🔐 Попытка авторизации...")                # Пробуем получить информацию об API без авторизации        try:            response = requests.get(f"{base_url}/api", timeout=5)            print(f"✅ API доступен: {response.status_code}")        except requests.exceptions.ConnectionError:            print("❌ Сервер не запущен. Запустите сервер командой: python main.py")            return False                # Пробуем создать папку без авторизации (должна вернуть 401)        print("\n📁 Попытка создать папку без авторизации...")        response = requests.post(f"{base_url}/folders/", json=folder_data, timeout=5)        print(f"Статус: {response.status_code}")        print(f"Ответ: {response.text}")                if response.status_code == 401:            print("✅ Авторизация работает корректно (401 Unauthorized)")        else:            print(f"⚠️ Неожиданный статус: {response.status_code}")                return True            except Exception as e:        print(f"❌ Ошибка при тестировании: {e}")        return Falsedef test_folder_model():    """Тестировать модель папки"""    print("\n🔧 Тестируем модель папки...")        try:        from models.folder import Folder, FolderCreate, FolderPublic        from services.folders.folder_service import FolderService                # Тестируем создание модели        folder_data = FolderCreate(            name="Тестовая папка",            description="Описание",            folder_type="custom",            chat_ids=[1, 2, 3],            agent_ids=[1, 2],            settings={"test": "value"}        )                print(f"✅ FolderCreate создана: {folder_data.name}")                # Тестируем сервис        folder_service = FolderService()        print("✅ FolderService создан")                return True            except Exception as e:        print(f"❌ Ошибка при тестировании модели: {e}")        return Falseif __name__ == "__main__":    print("🚀 Запуск тестов создания папки")    print("=" * 50)        # Тестируем модель    if test_folder_model():        print("✅ Модель папки работает корректно")    else:        print("❌ Проблемы с моделью папки")        # Тестируем API    if test_folder_creation():        print("✅ API тест завершен")    else:        print("❌ Проблемы с API")